```python
def smallestBeautifulSubstring(s, k):
    n = len(s)
    min_length = float('inf')
    candidates = []

    # Find all beautiful substrings and track the minimum length
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                length = j - i + 1
                if length < min_length:
                    min_length = length
                    candidates = [s[i:j+1]]
                elif length == min_length:
                    candidates.append(s[i:j+1])
                break
            elif ones_count > k:
                break

    # If no beautiful substring found
    if not candidates:
        return ""

    # Return lexicographically smallest substring
    return min(candidates)
```

