def minimumSum(nums):
    n = len(nums)
    min_sum = float('inf')
    found = False

    # Iterate through all possible triplets (i, j, k)
    # Since constraints are small (n <= 50), O(n^3) is acceptable.
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] < nums[j] and nums[k] < nums[j]:
                    current_sum = nums[i] + nums[j] + nums[k]
                    if current_sum < min_sum:
                        min_sum = current_sum
                        found = True

    return min_sum if found else -1
```

