def countCompleteSubstrings(word, k):
    def isValidAdjacent(s):
        for i in range(len(s) - 1):
            if abs(ord(s[i]) - ord(s[i + 1])) > 2:
                return False
        return True

    def isValidFrequency(s, k):
        from collections import Counter
        freq = Counter(s)
        for count in freq.values():
            if count != k:
                return False
        return True

    n = len(word)
    count = 0

    # Check all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = word[i:j]
            # Length must be a multiple of k for each character to appear exactly k times
            if len(substring) % k != 0:
                continue

            # The number of unique characters must be len(substring) // k
            unique_chars = len(set(substring))
            if len(substring) != unique_chars * k:
                continue

            # Check adjacent character constraint
            if not isValidAdjacent(substring):
                continue

            # Check frequency constraint
            if isValidFrequency(substring, k):
                count += 1

    return count
```

