                for j in range(26):
                    if dist[k][j] != inf:
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')

        if dist[u][v] == inf:
            return -1

        total_cost += dist[u][v]

    return total_cost
