def canSortArray(nums):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Group elements by their set bit count
    bit_groups = {}
    for i, num in enumerate(nums):
        bit_count = count_set_bits(num)
        if bit_count not in bit_groups:
            bit_groups[bit_count] = []
        bit_groups[bit_count].append(num)

    # Sort each group individually
    for bit_count in bit_groups:
        bit_groups[bit_count].sort()

    # Reconstruct the array according to original bit count order
    result = []
    for num in nums:
        bit_count = count_set_bits(num)
        result.append(bit_groups[bit_count][0])
        bit_groups[bit_count].pop(0)

    # Check if the reconstructed array is sorted
    return result == sorted(nums)
