def lastNonEmptyString(s):
    # Count frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Characters that will remain just before the last operation
    # are those that appear max_freq times
    remaining_chars = set()
    for char, count in freq.items():
        if count == max_freq:
            remaining_chars.add(char)

    # Extract the characters in their original order, but only those that will remain
    result = []
    # We need to track how many times we've seen each character
    seen_count = {}

    for char in s:
        # Initialize count if not seen before
        if char not in seen_count:
            seen_count[char] = 0

        # Increment the count for this character
        seen_count[char] += 1

        # If this character is one of the ones that will remain
        # and we're seeing it for the last time (at max_freq)
        if char in remaining_chars and seen_count[char] == max_freq:
            result.append(char)

    return ''.join(result)
