def maxPalindromes(words):
    # Count frequency of each character across all words
    char_count = {}
    for word in words:
        for char in word:
            char_count[char] = char_count.get(char, 0) + 1

    # Count total pairs of characters available (each pair can be used on both sides of palindrome)
    total_pairs = 0
    for count in char_count.values():
        total_pairs += count // 2

    # Sort words by length in ascending order to maximize the number of palindromes
    # (greedy approach: make shorter words palindrome first)
    word_lengths = sorted([len(word) for word in words])

    palindromes_count = 0
    for length in word_lengths:
        # Pairs needed for a palindrome of given length
        pairs_needed = length // 2

        if total_pairs >= pairs_needed:
            total_pairs -= pairs_needed
            palindromes_count += 1

    return palindromes_count
