            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    # BFS to find shortest distance between any two points
    def bfs_dist(start_pos, end_pos):
        if start_pos == end_pos:
            return 0
        visited = [[False] * W for _ in range(H)]
        queue = deque([(start_pos[0], start_pos[1], 0)])
        visited[start_pos[0]][start_pos[1]] = True

        while queue:
            r, c, d = queue.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc] and grid[nr][nc] != '#':
                    if (nr, nc) == end_pos:
                        return d + 1
                    visited[nr][nc] = True
                    queue.append((nr, nc, d + 1))
        return -1  # unreachable

    # Get distance from start to goal and from start to each candy
    start_to_goal = bfs_dist(start, goal)
    if start_to_goal > T:
        print(-1)
        return

    # If no candies, just check if we can reach goal
    if not candies:
        print(0)
        return

    # Compute distances between start, goal, and all candies
    n_candies = len(candies)
    # dist[i][j] = distance between candy i and candy j
    candy_dist = [[0] * n_candies for _ in range(n_candies)]
    for i in range(n_candies):
        for j in range(i+1, n_candies):
            d = bfs_dist(candies[i], candies[j])
            candy_dist[i][j] = d
            candy_dist[j][i] = d

    # dist from start to each candy
    start_to_candy = []
    for candy in candies:
        d = bfs_dist(start, candy)
        start_to_candy.append(d)

    # dist from each candy to goal
    candy_to_goal = []
    for candy in candies:
        d = bfs_dist(candy, goal)
        candy_to_goal.append(d)

    # Check if any candy is unreachable
    for d in start_to_candy:
        if d == -1:
            continue  # we'll handle this in state traversal

    for d in candy_to_goal:
        if d == -1:
            continue  # we'll handle this in state traversal

    # Use DP with bitmasks to find maximum candies we can collect
    # dp[mask][i] = minimum steps to collect candies in mask and end at candy i
    INF = float('inf')
    from collections import defaultdict
    dp = defaultdict(lambda: defaultdict(lambda: INF))

    # Initialize: start from start, go to each candy
    for i in range(n_candies):
        if start_to_candy[i] != -1:
            dp[1 << i][i] = start_to_candy[i]

    # Also consider the case where we go directly to goal without collecting any candy
    best = 0 if start_to_goal <= T else -INF

    # Process all masks
    for mask in range(1 << n_candies):
        for i in range(n_candies):
            if dp[mask][i] == INF:
                continue
            current_steps = dp[mask][i]
            # Try to go to goal from candy i
            total_steps = current_steps + candy_to_goal[i]
            if total_steps <= T:
                best = max(best, bin(mask).count('1'))

            # Try to go to other candies
            for j in range(n_candies):
                if mask & (1 << j):  # already visited j
                    continue
                if candy_dist[i][j] == -1:  # unreachable
                    continue
                new_steps = current_steps + candy_dist[i][j]
                if new_steps < dp[mask | (1 << j)][j]:
                    dp[mask | (1 << j)][j] = new_steps

    # Also check paths that don't collect any candy
    if start_to_goal <= T:
        best = max(best, 0)

    if best == -INF:
        print(-1)
    else:
        print(best)

solve()
