        index += 1
        s = list(map(int, data[index:index + a]))
        index += a
        sets.append(set(s))

    # Check if any set already contains both 1 and M
    for s in sets:
        if 1 in s and m in s:
            print(0)
            return

    # Build a graph where nodes are integers from 1 to M
    # and edges represent that two numbers appear in the same set
    graph = defaultdict(list)

    for s in sets:
        elements = list(s)
        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                u, v = elements[i], elements[j]
                if v not in graph[u]:
                    graph[u].append(v)
                if u not in graph[v]:
                    graph[v].append(u)

    # Check connectivity from 1 to M using BFS
    if 1 not in graph and m not in graph:
        print(-1)
        return

    # BFS to find shortest path from 1 to M
    queue = deque([(1, 0)])  # (node, distance)
    visited = {1}

    while queue:
        node, dist = queue.popleft()

        if node == m:
            # The distance in the graph is the number of edges (steps between numbers)
            # But each union operation can connect multiple components
            # We need to think in terms of connected components of sets
            break

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    else:
        # No path from 1 to M
        print(-1)
        return

    # Now we know 1 and M are in the same connected component of numbers
    # But we need to compute minimum union operations to merge sets
    # This is equivalent to: if we consider each initial set as a node,
    # and connect sets that share an element, then we want the shortest path
    # in terms of number of unions to connect a set containing 1 with a set containing M

    # Build set graph: each set is a node, connect sets that share at least one element
    set_graph = defaultdict(list)
    element_to_sets = defaultdict(list)

    for i, s in enumerate(sets):
        for elem in s:
            element_to_sets[elem].append(i)

    # Connect sets that share elements
    for elem, set_indices in element_to_sets.items():
        for i in range(len(set_indices)):
            for j in range(i + 1, len(set_indices)):
                u, v = set_indices[i], set_indices[j]
                if v not in set_graph[u]:
                    set_graph[u].append(v)
                if u not in set_graph[v]:
                    set_graph[v].append(u)

    # Find all sets containing 1 and all sets containing M
    sets_with_1 = []
    sets_with_m = []

    for i, s in enumerate(sets):
        if 1 in s:
            sets_with_1.append(i)
        if m in s:
            sets_with_m.append(i)

    if not sets_with_1 or not sets_with_m:
        print(-1)
        return

    # BFS from all sets containing 1 to any set containing M
    queue = deque()
    visited = set()

    for start_set in sets_with_1:
