def solve():
    import sys
    from itertools import combinations

    # Read input
    data = sys.stdin.read().split()
    N = int(data[0])
    T = int(data[1])
    M = int(data[2])

    # Read incompatible pairs
    incompatible = set()
    for i in range(M):
        a = int(data[3 + i*2])
        b = int(data[3 + i*2 + 1])
        incompatible.add((min(a, b), max(a, b)))

    # Generate all possible ways to divide N players into T non-empty teams
    # We'll use recursive backtracking to assign players to teams
    def count_ways():
        if T > N or T <= 0:
            return 0

        # Use dynamic programming with bit masks
        # But since N <= 10, we can use a simpler approach with recursion
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def backtrack(player, teams_tuple):
            # Convert teams representation to a canonical form
            # teams[i] = team number of player i+1
            if player > N:
                # Check if we have exactly T teams
                teams_set = set(teams_tuple)
                if len(teams_set) != T:
                    return 0

                # Check incompatible pairs
                for i in range(N):
                    for j in range(i+1, N):
                        if (i+1, j+1) in incompatible or (j+1, i+1) in incompatible:
                            if teams_tuple[i] == teams_tuple[j]:
                                return 0
                return 1

            total = 0
            # Try to assign current player to each existing team
            existing_teams = set(teams_tuple[:player-1])
            for team in existing_teams:
                new_teams = teams_tuple[:player-1] + (team,)
                total += backtrack(player + 1, new_teams)

            # Try to assign current player to a new team (if we haven't reached T teams yet)
            if len(existing_teams) < T:
                new_team = max(existing_teams) + 1 if existing_teams else 1
                new_teams = teams_tuple[:player-1] + (new_team,)
                total += backtrack(player + 1, new_teams)

            return total

        return backtrack(1, tuple())

    # Alternative approach: use inclusion-exclusion with direct enumeration
    # Since N is small (<= 10), we can enumerate all possible assignments
    def count_direct():
        from itertools import product

        count = 0
        # Generate all possible assignments of N players to T teams
        for assignment in product(range(1, T + 1), repeat=N):
            # Check if exactly T teams are used
            if len(set(assignment)) != T:
                continue

            # Check incompatible pairs
            valid = True
            for i in range(N):
                for j in range(i + 1, N):
                    if (i + 1, j + 1) in incompatible or (j + 1, i + 1) in incompatible:
                        if assignment[i] == assignment[j]:
                            valid = False
                            break
                if not valid:
                    break

            if valid:
                count += 1

        return count

    result = count_direct()
    print(result)

solve()
