    from collections import defaultdict

    # Read input
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])

    # Build the graph of known relations
    stronger = defaultdict(set)  # stronger[x] = set of people that x is stronger than

    index = 2
    for _ in range(m):
        a = int(data[index])
        b = int(data[index + 1])
        index += 2
        stronger[a].add(b)

    # Use transitivity to infer all possible relations (Floyd-Warshall style)
    # We'll compute the full "is stronger than" relation
    # can_defeat[i][j] = True if i is stronger than j
    can_defeat = [[False] * (n + 1) for _ in range(n + 1)]

    # Initialize with direct information
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                continue
            if j in stronger[i]:
                can_defeat[i][j] = True

    # Apply transitivity: if a > b and b > c, then a > c
    # Use Floyd-Warshall algorithm
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if i == j:
                    continue
                if can_defeat[i][k] and can_defeat[k][j]:
                    can_defeat[i][j] = True

    # Find candidates for strongest programmer
    # A person is strongest if they are stronger than all others
    candidates = []

    for person in range(1, n + 1):
        is_strongest = True
        for other in range(1, n + 1):
            if person == other:
                continue
            if not can_defeat[person][other]:
                is_strongest = False
                break
        if is_strongest:
            candidates.append(person)

    # If exactly one candidate, return it; otherwise return -1
    if len(candidates) == 1:
        print(candidates[0])
    else:
        print(-1)

