def solve():
    import sys
    input = sys.stdin.read
    lines = input().strip().split('\n')

    # Read the three polyominoes
    polyominoes = []
    for i in range(3):
        grid = []
        for j in range(4):
            grid.append(lines[i * 4 + j])
        polyominoes.append(grid)

    def get_shape_cells(grid):
        """Extract the relative coordinates of '#' cells in the polyomino."""
        cells = []
        for i in range(4):
            for j in range(4):
                if grid[i][j] == '#':
                    cells.append((i, j))
        return cells

    def normalize(cells):
        """Normalize the shape by shifting to top-left origin."""
        if not cells:
            return set()
        min_i = min(x for x, y in cells)
        min_j = min(y for x, y in cells)
        return set((x - min_i, y - min_j) for x, y in cells)

    def rotate(shape):
        """Rotate the shape 90 degrees clockwise."""
        return set((y, -x) for x, y in shape)

    def get_all_transforms(shape):
        """Get all rotations (0°, 90°, 180°, 270°) of the shape."""
        transforms = []
        current = shape
        for _ in range(4):
            normalized = normalize([(x, y) for x, y in current])
            if normalized not in transforms:
                transforms.append(normalized)
            current = rotate(current)
        return transforms

    # Get the base shape (set of relative coordinates) for each polyomino
    base_shapes = []
    for grid in polyominoes:
        cells = get_shape_cells(grid)
        base_shape = normalize(cells)
        base_shapes.append(base_shape)

    # Get all possible transformations (rotations) for each polyomino
    poly_transforms = []
    for shape in base_shapes:
        poly_transforms.append(get_all_transforms(shape))

    def fits_in_grid(shape, top, left):
        """Check if placing the shape at (top, left) fits in the 4x4 grid."""
        for dx, dy in shape:
            x, y = top + dx, left + dy
            if not (0 <= x < 4 and 0 <= y < 4):
                return False
        return True

    def place(shape, top, left):
        """Return the set of grid positions covered when placing the shape at (top, left)."""
        return {(top + dx, left + dy) for (dx, dy) in shape}

    def solve_puzzle():
        # Try all combinations of transformations and placements
        from itertools import permutations

        # Try all permutations of the three polyominoes
        for perm in permutations(range(3)):
            for t0 in poly_transforms[perm[0]]:
                for r0 in range(4):
                    for c0 in range(4):
                        if not fits_in_grid(t0, r0, c0):
                            continue
                        placed0 = place(t0, r0, c0)

                        for t1 in poly_transforms[perm[1]]:
                            for r1 in range(4):
                                for c1 in range(4):
                                    if not fits_in_grid(t1, r1, c1):
                                        continue
                                    placed1 = place(t1, r1, c1)
                                    if placed0 & placed1:  # overlap
                                        continue

                                    for t2 in poly_transforms[perm[2]]:
                                        for r2 in range(4):
                                            for c2 in range(4):
                                                if not fits_in_grid(t2, r2, c2):
                                                    continue
                                                placed2 = place(t2, r2, c2)
                                                if placed0 & placed2 or placed1 & placed2:
                                                    continue

                                                # Check if union covers entire 4x4 grid
                                                total = placed0 | placed1 | placed2
                                                if len(total) == 16:
                                                    return True
        return False

    if solve_puzzle():
        print("Yes")
    else:
        print("No")

solve()
