def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True

    if 1 in nums:
        return False

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Union-Find data structure
    parent = list(range(len(nums)))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # For each prime factor, group all numbers that have this factor
    prime_to_indices = {}

    for i, num in enumerate(nums):
        temp = num
        # Find all prime factors of num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                # d is a prime factor
                if d not in prime_to_indices:
                    prime_to_indices[d] = []
                prime_to_indices[d].append(i)

                while temp % d == 0:
                    temp //= d
            d += 1

        # If temp > 1, then it's a prime factor
        if temp > 1:
            if temp not in prime_to_indices:
                prime_to_indices[temp] = []
            prime_to_indices[temp].append(i)

    # Union all indices that share common prime factors
    for indices in prime_to_indices.values():
        for j in range(1, len(indices)):
            union(indices[0], indices[j])

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, len(nums)):
        if find(i) != root:
            return False

    return True
