def smallestString(s: str) -> str:
    # Convert string to list for mutability
    s_list = list(s)
    n = len(s_list)

    # Find the first character that is not 'a'
    start = -1
    for i in range(n):
        if s_list[i] != 'a':
            start = i
            break

    # If the string consists only of 'a's, we must change the last character to 'z'
    # to make it lexicographically smallest (as per the rules of the operation)
    if start == -1:
        s_list[-1] = 'z'
        return "".join(s_list)

    # From the first non-'a' character, change characters until we hit another 'a'
    # or reach the end of the string.
    for i in range(start, n):
        if s_list[i] == 'a':
            break
        # Shift character back by one (a becomes z, b becomes a, etc.)
        s_list[i] = chr(ord(s_list[i]) - 1)

    return "".join(s_list)
