def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs satisfy the divisibility condition
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                compatible[i][j] = True

    # dp[mask][last] = number of ways to arrange the numbers in mask with last number at position last
    # We'll use memoization with bitmasks
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(mask, last_idx):
        # Count how many bits are set in mask
        count = bin(mask).count('1')
        if count == n:
            return 1

        total = 0
        for next_idx in range(n):
            # If this number is not used yet and is compatible with the last number
            if not (mask & (1 << next_idx)) and compatible[last_idx][next_idx]:
                total = (total + dp(mask | (1 << next_idx), next_idx)) % MOD

        return total

    # Try starting with each number
    result = 0
    for i in range(n):
        result = (result + dp(1 << i, i)) % MOD

    return result
