def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    median_idx = (n - 1) // 2  # For 0-indexed array, this gives the correct median index
    median = nums[median_idx]

    if median == k:
        return 0

    operations = 0

    if median < k:
        # Need to increase median to k
        # All elements from median index onwards that are less than k need to be increased
        for i in range(median_idx, n):
            if nums[i] < k:
                operations += k - nums[i]
    else:
        # Need to decrease median to k
        # All elements from median index and before that are greater than k need to be decreased
        for i in range(median_idx + 1):
            if nums[i] > k:
                operations += nums[i] - k

    return operations
