def findKthSmallestAmount(coins, k):
    def count_multiples(coin, max_val):
        return max_val // coin

    def count_total_multiples(max_val):
        count = 0
        n = len(coins)
        # Use inclusion-exclusion principle
        for mask in range(1, 1 << n):
            lcm_val = 1
            bit_count = 0
            valid = True

            for i in range(n):
                if mask & (1 << i):
                    # Calculate LCM of selected coins
                    import math
                    lcm_val = lcm_val * coins[i] // math.gcd(lcm_val, coins[i])
                    # Check for overflow
                    if lcm_val > max_val:
                        valid = False
                        break
                    bit_count += 1

            if valid:
                if bit_count % 2 == 1:
                    count += max_val // lcm_val
                else:
                    count -= max_val // lcm_val

        return count

    # Binary search on the answer
    left, right = 1, k * min(coins)

    while left < right:
        mid = (left + right) // 2
        if count_total_multiples(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left
