    # dp[i] represents the maximum number of jumps to reach index i
    dp = [-1] * n
    dp[0] = 0  # We start at index 0, so 0 jumps needed

    for i in range(1, n):
        for j in range(i):
            if dp[j] != -1:  # If we can reach index j
                diff = nums[i] - nums[j]
                if -target <= diff <= target:
                    if dp[i] == -1:
                        dp[i] = dp[j] + 1
                    else:
                        dp[i] = max(dp[i], dp[j] + 1)

    return dp[n-1]
