def minimumString(a: str, b: str, c: str) -> str:
    def merge(s1, s2):
        # If s2 is already in s1, return s1
        if s2 in s1:
            return s1

        # Find the maximum overlap of suffix of s1 with prefix of s2
        max_overlap = 0
        for i in range(1, min(len(s1), len(s2)) + 1):
            if s1[-i:] == s2[:i]:
                max_overlap = i

        return s1 + s2[max_overlap:]

    def combine_all(perm):
        result = perm[0]
        for i in range(1, 3):
            result = merge(result, perm[i])
        return result

    # Try all permutations of the three strings
    permutations = [
        [a, b, c],
        [a, c, b],
        [b, a, c],
        [b, c, a],
        [c, a, b],
        [c, b, a]
    ]

    best_result = None

    for perm in permutations:
        candidate = combine_all(perm)
        if best_result is None or len(candidate) < len(best_result):
            best_result = candidate
        elif len(candidate) == len(best_result) and candidate < best_result:
            best_result = candidate

    return best_result
