def minChanges(s: str, k: int) -> int:
    n = len(s)

    # Precompute the cost to make each substring a semi-palindrome
    def get_cost(sub):
        length = len(sub)
        if length == 1:
            return 1  # single char cannot be semi-palindrome by definition

        min_cost = float('inf')

        # Try all possible divisors d where 1 <= d < length and length % d == 0
        for d in range(1, length):
            if length % d != 0:
                continue

            cost = 0
            # For each residue class modulo d
            for r in range(d):
                # Get all characters at positions with index % d == r
                chars = []
                for i in range(r, length, d):
                    chars.append(sub[i])

                # Check how many changes needed to make this sequence a palindrome
                m = len(chars)
                for i in range(m // 2):
                    if chars[i] != chars[m - 1 - i]:
                        cost += 1

            min_cost = min(min_cost, cost)

        return min_cost if min_cost != float('inf') else 0

    # Precompute cost for all substrings
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n + 1):
            if j - i > 1:  # length > 1
                cost[i][j-1] = get_cost(s[i:j])
            # length 1 cannot be semi-palindrome, but we'll handle in DP

    # DP: dp[i][p] = minimum cost to partition s[0:i] into p semi-palindrome substrings
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k + 1, i + 1)):
            # Try all possible last substring ending at i-1
            for j in range(p - 1, i):  # j is start index of last substring
                if i - j > 1:  # substring length > 1 (required for semi-palindrome)
                    if dp[j][p-1] != INF:
                        dp[i][p] = min(dp[i][p], dp[j][p-1] + cost[j][i-1])

    return dp[n][k]
```

