def longestValidSubstring(word, forbidden):
    forbidden_set = set(forbidden)
    n = len(word)
    max_len = 0

    # For each starting position, find the longest valid substring
    for i in range(n):
        for j in range(i, n):
            # Check if substring word[i:j+1] is valid
            substring = word[i:j+1]
            valid = True

            # Check all possible substrings of the current substring
            for length in range(1, len(substring) + 1):
                for k in range(len(substring) - length + 1):
                    if substring[k:k+length] in forbidden_set:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                max_len = max(max_len, j - i + 1)
            else:
                # If current substring is invalid, longer ones starting at i will also be invalid
                break

    return max_len
