def productMatrix(grid):
    n = len(grid)
    m = len(grid[0])
    total_elements = n * m
    MOD = 12345

    # Calculate total product of all elements
    total_product = 1
    for i in range(n):
        for j in range(m):
            total_product = (total_product * grid[i][j]) % MOD

    # Create result matrix
    result = []
    for i in range(n):
        row = []
        for j in range(m):
            # Calculate product excluding grid[i][j]
            # If grid[i][j] is 0, we need to handle it specially
            if grid[i][j] == 0:
                # If there's exactly one zero in the matrix, the product excluding that zero is non-zero
                # But if there are multiple zeros, the product excluding any zero will still be 0
                product_excluding = 1
                zero_count = 0
                for ii in range(n):
                    for jj in range(m):
                        if ii == i and jj == j:
                            continue
                        if grid[ii][jj] == 0:
                            zero_count += 1
                        product_excluding = (product_excluding * grid[ii][jj]) % MOD

                if zero_count > 0:
                    row.append(0)
                else:
                    row.append(product_excluding)
            else:
                # Use modular multiplicative inverse to divide
                # (total_product * mod_inverse(grid[i][j], MOD)) % MOD
                # But simpler approach: recalculate without current element
                product_excluding = 1
                for ii in range(n):
                    for jj in range(m):
                        if not (ii == i and jj == j):
                            product_excluding = (product_excluding * grid[ii][jj]) % MOD
                row.append(product_excluding)
        result.append(row)

    return result
